/*@ requires n > 0;
    requires n ≤ 18446744073709551615UL / 1 - 7;
    requires \valid_read(input + (0 .. (n + 7) - 1));
    requires \valid(left + (0 .. n - 1));
    requires \valid(right + (0 .. n - 1));
    requires \valid_read(params);
    requires \separated(left + (0 .. n - 1), right + (0 .. n - 1));
    requires \separated(left + (0 .. n - 1), input + (0 .. (n + 7) - 1));
    requires \separated(left + (0 .. n - 1), params);
    requires \separated(right + (0 .. n - 1), input + (0 .. (n + 7) - 1));
    requires \separated(right + (0 .. n - 1), params);
    requires params->scalar.multiplier ≢ -2147483647 - 1;
    terminates \true;
    exits \false;
    ensures equal: \result ≡ 1;
    assigns *(left + (0 .. n - 1)), *(right + (0 .. n - 1));
 */
int equivalent(size_t n, int8_t const *input, int8_t *left, int8_t *right,
               struct xnn_qs8_cvt_params const *params)
{
  int __retres;
  test_neon(n,input,left,params);
  /*@
  assert
    ∀ ℤ j;
      0 ≤ j < n ⇒
      *(left + j) ≡
      L_cvt8(*(input + j), params->scalar.input_zero_point,
            params->scalar.multiplier, params->scalar.output_zero_point);
   */
  ;
  test_rvv(n,input,right,params);
  /*@ assert ∀ ℤ j; 0 ≤ j < n ⇒ *(left + j) ≡ *(right + j); */ ;
  {
    size_t i = (size_t)0;
    /*@ loop invariant 0 ≤ i ≤ n;
        loop assigns i;
        loop variant n - i; */
    while (i < n) {
      /*@ assert rte: mem_access: \valid_read(left + i); */
      /*@ assert rte: mem_access: \valid_read(right + i); */
      if (! ((int)*(left + i) == (int)*(right + i))) {
        __retres = 0;
        goto return_label;
      }
      i ++;
    }
  }
  __retres = 1;
  return_label: return __retres;
}

